const $=(s,root=document)=>root.querySelector(s),$$=(s,root=document)=>[...root.querySelectorAll(s)];
const app={view:'dashboard',seconds:0,attacks:0,runCount:0,language:'C++',currentMatchId:null,token:null,user:null,team:null,socket:null,saveTimer:null,code:{'C':'','C++':''}};
async function api(path,options={}){const response=await fetch(`/api${path}`,{credentials:'same-origin',headers:{'content-type':'application/json',...(app.token?{authorization:`Bearer ${app.token}`}:{})},...options});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error?.message||`Request failed (${response.status})`);return data}
const teams=[{rank:1,name:'Runtime Terrors',tag:'RT',points:'1,860',record:'5–0',change:'↑ 2',color:'lime'},{rank:2,name:'Stack Smashers',tag:'SS',points:'1,720',record:'4–1',change:'↑ 1',color:'violet'},{rank:3,name:'Ctrl Alt Elite',tag:'CE',points:'1,580',record:'4–1',change:'↑ 4',color:'blue'},{rank:4,name:'Bug Bounty Hunters',tag:'BH',points:'1,460',record:'4–1',change:'↓ 1',color:'yellow'},{rank:5,name:'Null Pointers',tag:'NP',points:'1,380',record:'3–2',change:'↑ 2',color:'salmon'},{rank:8,name:'Byte Me',tag:'BM',points:'1,240',record:'3–1',change:'↑ 3',color:'lime',you:true},{rank:9,name:'Syntax Squad',tag:'SQ',points:'1,180',record:'3–2',change:'—',color:'violet'},{rank:10,name:'404 Brain Not Found',tag:'404',points:'1,120',record:'3–2',change:'↓ 2',color:'blue'}];
const escapeHtml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function participantField(i){return `<fieldset class="roster-member-form"><legend>PARTICIPANT ${String(i+1).padStart(2,'0')}${i===0?' · CAPTAIN':''}</legend><label for="member${i}Name">Full name</label><input id="member${i}Name" name="member${i}Name" required minlength="2" maxlength="80" autocomplete="name"><label for="member${i}Email">Email address</label><input id="member${i}Email" name="member${i}Email" type="email" required maxlength="254" autocomplete="email">${i===0?`<label for="member${i}Password">Captain password</label><input id="member${i}Password" name="member${i}Password" type="password" required minlength="12" maxlength="200" autocomplete="new-password" placeholder="At least 12 characters">`:''}</fieldset>`}
function toast(message){const el=document.createElement('div');el.className='toast';el.innerHTML=`<i></i><span>${escapeHtml(message)}</span>`;$('#toastRegion').append(el);setTimeout(()=>{el.style.opacity='0';el.style.transform='translateY(5px)';setTimeout(()=>el.remove(),220)},3200)}
function navigate(view){const button=$(`.nav-item[data-view="${view}"]`);if(!button&&view!=='dashboard')return;app.view=view;$$('.view').forEach(v=>v.classList.toggle('active',v.id===`view-${view}`));$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===view));const label=button?.textContent.trim().replace(/\s+LIVE$/,'')||'Overview';$('#breadcrumbCurrent').textContent=label;$('#sidebar').classList.remove('open');if(view!=='dashboard')renderView(view);window.scrollTo({top:0,behavior:'smooth'})}
function pageHead(kicker,title,description,action=''){return `<div class="view-page-head"><div><div class="overline"><span class="overline-line"></span> ${kicker}</div><h1>${title}</h1><p>${description}</p></div>${action}</div>`}
function renderMatch(){const el=$('#view-match');el.innerHTML=`${pageHead('LIVE MATCH','Match control room','The server controls the clock, submissions, and results.')}<div class="match-layout"><div><section class="panel editor-card"><div class="editor-top"><span class="file-tab"><i class="file-dot"></i> solution.cpp</span><select class="language-select" id="languageSelect"><option>C</option><option selected>C++</option></select><div class="editor-toolbar"><button class="button button-quiet" id="runCode">▶ Run public tests</button><button class="button button-lime" id="submitCode">Submit <span>→</span></button></div></div><textarea class="code-area" id="codeArea" spellcheck="false" aria-label="Code editor"></textarea><div class="editor-bottom"><span><i></i> Connected</span><span>UTF-8 · Ln <b id="lineCount">1</b></span></div></section><section class="panel console-panel"><div class="console-head"><strong>Execution results</strong><span id="consoleSummary">Run against public cases</span></div><div id="testResults"><div class="test-row">Public tests are run by the isolated judge.</div></div></section></div><aside class="match-side"><section class="panel side-card"><div class="challenge-label">CHALLENGE</div><h3>Loading challenge…</h3><p>Challenge details will appear here.</p></section><section class="panel side-card"><div class="timer-side"><div><div class="challenge-label">SERVER TIMER</div><strong class="side-timer">--:--</strong></div><span>LIVE</span></div><div class="timer-progress"><span></span></div></section><section class="panel side-card"><div class="side-card-title"><strong>Match status</strong><span id="matchStateLabel">CONNECTED</span></div><p>Both teams share this live match room. Disconnects do not stop the server timer.</p></section></aside></div>`;const area=$('#codeArea');area.value=app.code[app.language]||'';$('#languageSelect').value=app.language;$('#languageSelect').addEventListener('change',e=>{app.code[app.language]=area.value;app.language=e.target.value;$('.file-tab').innerHTML=`<i class="file-dot"></i> solution.${app.language==='C'?'c':'cpp'}`;area.value=app.code[app.language]||''});$('#runCode').addEventListener('click',runCode);$('#submitCode').addEventListener('click',submitCode);area.addEventListener('keydown',e=>{if(e.key==='Tab'){e.preventDefault();const start=area.selectionStart,end=area.selectionEnd;area.value=area.value.substring(0,start)+'    '+area.value.substring(end);area.selectionStart=area.selectionEnd=start+4;area.dispatchEvent(new Event('input'))}})}
async function runCode(){if(!app.currentMatchId){toast('No active match is assigned to your account.');return}app.runCount++;$('#consoleSummary').textContent='Running against public tests…';$('#testResults').innerHTML='<div class="test-row">◌ &nbsp; Waiting for isolated execution service</div>';try{const result=await api(`/matches/${app.currentMatchId}/run`,{method:'POST',body:JSON.stringify({sourceCode:$('#codeArea').value,language:languageCode(app.language)})});$('#consoleSummary').textContent=result.status==='runner_unavailable'?'Execution service unavailable':`${result.passed} of ${result.total} public tests passed`;$('#testResults').innerHTML=result.results.map((r,i)=>`<div class="test-row"><span style="color:${r.passed?'#9beaa1':'#ff9b80'}">${r.passed?'✓':'×'}</span> Public test case ${i+1} ${r.error?`· ${escapeHtml(r.error)}`:''}<span class="test-state ${r.passed?'':'pending'}">${r.passed?'PASSED':r.unavailable?'UNAVAILABLE':'FAILED'}</span></div>`).join('')||'<div class="test-row">No public test cases configured.</div>'}catch(e){$('#consoleSummary').textContent=e.message;$('#testResults').innerHTML=`<div class="test-row"><span style="color:#ff9b80">×</span> ${escapeHtml(e.message)} <span class="test-state pending">ERROR</span></div>`}}
async function submitCode(){if(!app.currentMatchId){toast('No active match is assigned to your account.');return}const btn=$('#submitCode');btn.disabled=true;btn.textContent='Checking…';try{const result=await api(`/matches/${app.currentMatchId}/submit`,{method:'POST',body:JSON.stringify({sourceCode:$('#codeArea').value,language:languageCode(app.language)})});$('#consoleSummary').textContent=result.status==='accepted'?'Hidden tests passed':result.status==='rejected'?'Hidden tests failed':'Submission status: '+result.status;$('#testResults').innerHTML=`<div class="test-row"><span style="color:${result.status==='accepted'?'#9beaa1':'#ff9b80'}">${result.status==='accepted'?'✓':'×'}</span> Hidden test result · ${result.passed} of ${result.total} cases passed <span class="test-state ${result.status==='accepted'?'':'pending'}">${result.status.toUpperCase()}</span></div>`;toast(result.status==='accepted'?'Accepted · your team won the match':'Submission evaluated by the server');addActivity('Submission evaluated',`${result.passed} of ${result.total} hidden test cases passed.`,'submit')}catch(e){toast(e.message)}finally{btn.disabled=false;btn.innerHTML='Submit solution <span>→</span>'}}
function languageCode(label){return label==='C++'?'cpp':label.toLowerCase()}
function addActivity(title,description,type='live'){const feed=$('#activityFeed');if(feed){const mark=type==='attack'?'↯':type==='submit'?'◉':'⌘',cl=type==='attack'?'marker-violet':type==='submit'?'marker-blue':'marker-lime';const row=document.createElement('article');row.className='activity-item';row.innerHTML=`<span class="activity-marker ${cl}">${mark}</span><div class="activity-body"><p><strong>${escapeHtml(title)}</strong></p><span>${escapeHtml(description)}</span></div><time>Just now</time>`;feed.prepend(row)}const log=$('#activityLogBody');if(log){const tr=document.createElement('tr');tr.innerHTML=`<td><span class="activity-type ${type}"><i></i>${escapeHtml(title)}</span></td><td>${escapeHtml(description)}</td><td>Match #M-024</td><td>Just now</td>`;log.prepend(tr)}}
function renderLeaderboard(){const el=$('#view-leaderboard');el.innerHTML=`${pageHead('LIVE STANDINGS','Leaderboard','Every bug found and every problem solved counts.')}<div class="stat-grid"><article class="stat-card panel"><div class="stat-top">TEAMS IN EVENT</div><div class="stat-value">60</div><div class="stat-foot"><span>5 groups · 12 teams each</span></div></article><article class="stat-card panel"><div class="stat-top">YOUR POSITION</div><div class="stat-value">#08 <span class="stat-trend">↑ 3</span></div><div class="stat-foot"><span>Top 14% of teams</span></div></article><article class="stat-card panel"><div class="stat-top">NEXT MILESTONE</div><div class="stat-value" style="font-size:19px">Semi-finals</div><div class="stat-foot"><span>Top 2 in Group C advance</span></div></article></div><section class="panel page-panel"><div class="section-heading"><div><div class="section-kicker">OVERALL · UPDATED LIVE</div><h3>Team standings</h3></div><span class="live-pill"><i></i> LIVE</span></div><table class="leaderboard-table"><thead><tr><th>RANK</th><th>TEAM</th><th>POINTS</th><th>RECORD</th><th>CHANGE</th><th>STATUS</th></tr></thead><tbody>${teams.map(t=>`<tr class="${t.you?'you':''}"><td>#${String(t.rank).padStart(2,'0')}</td><td><span class="team-cell"><i class="mini-team ${t.color}-avatar">${t.tag}</i>${t.name}${t.you?' <span class="activity-tag">YOU</span>':''}</span></td><td class="mono">${t.points}</td><td class="mono">${t.record}</td><td><span class="rank-change">${t.change}</span></td><td>${t.you?'<span class="live-pill"><i></i> IN MATCH</span>':'<span style="color:#8c929d">Active</span>'}</td></tr>`).join('')}</tbody></table></section>`}
function renderTournament(){const el=$('#view-tournament');el.innerHTML=`${pageHead('TOURNAMENT · 60 TEAMS','The road to the final','Every round is another chance to climb.')}<div class="subnav-tabs"><button class="selected" data-tab="bracket">Bracket view</button><button data-tab="groups">Group C</button><button data-tab="format">Tournament format</button></div><div id="tournamentPanel"><div class="stat-grid"><article class="stat-card panel"><div class="stat-top">CURRENT ROUND</div><div class="stat-value" style="font-size:19px">Group stage</div><div class="stat-foot"><span>Round 2 of 4</span></div></article><article class="stat-card panel"><div class="stat-top">MATCHES COMPLETE</div><div class="stat-value">20<span class="stat-trend">of 30</span></div><div class="stat-foot"><span>10 matches in progress</span></div></article><article class="stat-card panel"><div class="stat-top">ADVANCING</div><div class="stat-value">10<span class="stat-trend">teams</span></div><div class="stat-foot"><span>Top 2 teams per group</span></div></article></div><section class="panel page-panel"><div class="section-heading"><div><div class="section-kicker">GROUP C · MATCHDAY 2</div><h3>Group C standings</h3></div><span class="live-pill"><i></i> 2 MATCHES LIVE</span></div><table class="leaderboard-table"><thead><tr><th>POS</th><th>TEAM</th><th>PTS</th><th>W</th><th>L</th><th>STATUS</th></tr></thead><tbody><tr><td>01</td><td><span class="team-cell"><i class="mini-team lime-avatar">BM</i>Byte Me <span class="activity-tag">YOU</span></span></td><td class="mono">540</td><td>3</td><td>1</td><td><span class="live-pill"><i></i> PLAYING</span></td></tr><tr><td>02</td><td><span class="team-cell"><i class="mini-team violet-avatar">SQ</i>Syntax Squad</span></td><td class="mono">510</td><td>3</td><td>1</td><td><span class="live-pill"><i></i> PLAYING</span></td></tr><tr><td>03</td><td><span class="team-cell"><i class="mini-team blue-avatar">NP</i>Null Pointers</span></td><td class="mono">360</td><td>2</td><td>2</td><td>Waiting</td></tr><tr><td>04</td><td><span class="team-cell"><i class="mini-team yellow-avatar">CO</i>Commit Often</span></td><td class="mono">290</td><td>2</td><td>2</td><td>Waiting</td></tr><tr><td>05</td><td><span class="team-cell"><i class="mini-team violet-avatar">SD</i>Segfault Dragons</span></td><td class="mono">180</td><td>1</td><td>3</td><td>Waiting</td></tr><tr><td>06</td><td><span class="team-cell"><i class="mini-team blue-avatar">DD</i>Digital Deities</span></td><td class="mono">100</td><td>0</td><td>4</td><td>Waiting</td></tr></tbody></table></section></div>`;$$('.subnav-tabs button',el).forEach(btn=>btn.addEventListener('click',()=>{ $$('.subnav-tabs button',el).forEach(b=>b.classList.remove('selected'));btn.classList.add('selected');const panel=$('#tournamentPanel');if(btn.dataset.tab==='groups')panel.innerHTML='<section class="panel page-panel"><div class="section-kicker">GROUP C · MATCHDAY 2</div><h3 style="margin:5px 0 14px;font:600 15px var(--display)">Group C match schedule</h3>'+[['Byte Me','Syntax Squad','LIVE · MATCH #M-024'],['Null Pointers','Commit Often','TODAY · 11:15 AM'],['Segfault Dragons','Digital Deities','TODAY · 11:15 AM'],['Byte Me','Null Pointers','TODAY · 1:30 PM']].map(m=>`<div class="activity-item"><span class="activity-marker marker-lime">⌘</span><div class="activity-body"><p><strong>${m[0]} <span style="color:#747b87">vs</span> ${m[1]}</strong></p><span>Group C match</span></div><span class="bracket-status ${m[2].startsWith('LIVE')?'is-live':''}">${m[2]}</span></div>`).join('')+'</section>';else if(btn.dataset.tab==='format')panel.innerHTML='<section class="panel page-panel"><div class="section-kicker">HOW THE EVENT WORKS</div><h3 style="margin:5px 0 13px;font:600 15px var(--display)">From 60 teams to one champion</h3><div class="path-list" style="grid-template-columns:repeat(4,1fr)"><div class="path-step complete"><span class="path-node">✓</span><div class="path-copy"><strong>Qualifiers</strong><span>60 → 30 teams</span></div></div><div class="path-step current"><span class="path-node"><i></i></span><div class="path-copy"><strong>Group stage</strong><span>5 groups · top 2</span></div></div><div class="path-step locked"><span class="path-node">03</span><div class="path-copy"><strong>Semi-finals</strong><span>10 → 5 finalists</span></div></div><div class="path-step locked"><span class="path-node">04</span><div class="path-copy"><strong>Grand final</strong><span>5 teams compete</span></div></div></div><p style="margin-top:20px">During group matches, teams alternate between coder and detective roles. The grand final is a special challenge scored on correctness, completion time, and defense strategy.</p></section>';else renderTournament()}))}
function renderTeams(){const el=$('#view-teams');el.innerHTML=`${pageHead('TEAM DIRECTORY','Meet the teams','60 teams. Three to five people behind every strategy.')}<div class="stat-grid"><article class="stat-card panel"><div class="stat-top">REGISTERED TEAMS</div><div class="stat-value">60</div><div class="stat-foot"><span>All teams confirmed</span></div></article><article class="stat-card panel"><div class="stat-top">PLAYERS</div><div class="stat-value">180?300</div><div class="stat-foot"><span>3 to 5 participants per team</span></div></article><article class="stat-card panel"><div class="stat-top">YOUR GROUP</div><div class="stat-value">Group C</div><div class="stat-foot"><span>6 teams · 2 advance</span></div></article></div><div class="team-grid">${[['Byte Me','BM','#08 · 1,240 pts','Your team','lime'],['Syntax Squad','SQ','#09 · 1,180 pts','Group C · Rival','violet'],['Null Pointers','NP','#15 · 940 pts','Group C','blue'],['Commit Often','CO','#21 · 810 pts','Group C','yellow'],['Segfault Dragons','SD','#27 · 660 pts','Group C','salmon'],['Digital Deities','DD','#34 · 540 pts','Group C','violet']].map(t=>`<article class="panel roster-card"><div class="roster-top"><span class="roster-logo ${t[4]}-avatar">${t[1]}</span><div><h3>${t[0]}</h3><p>${t[3]}</p></div><span class="roster-score">${t[2].split('·')[1]||''}</span></div><div class="roster-members">${['AK','NP','RS','PM','DV'].map((m,i)=>`<i class="avatar avatar-${['lime','salmon','blue','violet','yellow','dark'][i]}">${m}</i>`).join('')}</div><div class="roster-foot"><span>3-5 MEMBERS</span><span>${t[2].split('·')[0]}</span></div></article>`).join('')}</div>`}
function renderProblems(){const el=$('#view-problems');el.innerHTML=`${pageHead('CHALLENGE LIBRARY','Problem archive','A peek at the challenges shaping this competition.')}<div class="subnav-tabs"><button class="selected">All problems</button><button>Completed</button><button>Coming up</button></div><div class="problem-list">${[['Signal in the Noise','Count quiet signal readings in a sequence.','MEDIUM','Round 02 · Active','⌘'],['The Missing Packet','Find the single missing value from a data stream.','EASY','Round 01 · Completed','↯'],['Palindrome Protocol','Validate a message against a set of mirror rules.','HARD','Round 03 · Coming up','⌁'],['Encrypted Coordinates','Decode a coordinate grid with a custom cipher.','MEDIUM','Semi-finals · Locked','▦'],['Five Subject Grades','Calculate totals, percentages, and final grades.','EASY','Practice challenge','▤']].map((p,i)=>`<article class="panel problem-row"><span class="problem-symbol">${p[4]}</span><div class="problem-copy"><strong>${p[0]}</strong><span>${p[1]}</span></div><span class="difficulty">${p[2]}</span><span class="problem-stat">${p[3]}</span></article>`).join('')}</div>`;$$('.subnav-tabs button',el).forEach(b=>b.addEventListener('click',()=>{$$('.subnav-tabs button',el).forEach(x=>x.classList.remove('selected'));b.classList.add('selected');toast(`${b.textContent.trim()} selected`)}))}
function renderActivity(){const el=$('#view-activity');el.innerHTML=`${pageHead('AUDIT TRAIL','Activity log','A clear record of what happened in your match.')}<section class="panel page-panel"><div class="section-heading"><div><div class="section-kicker">MATCH #M-024 · ROUND 02</div><h3>Recent events</h3></div><button class="button button-secondary" id="exportLog">↓ &nbsp;Export log</button></div><table class="activity-table"><thead><tr><th>EVENT</th><th>DETAILS</th><th>MATCH</th><th>TIME</th></tr></thead><tbody id="activityLogBody"><tr><td><span class="activity-type"><i></i>Match started</span></td><td>Round 2 against Syntax Squad began.</td><td>M-024</td><td>02:14 ago</td></tr><tr><td><span class="activity-type attack"><i></i>Attack applied</span></td><td>A controlled logic change was applied.</td><td>M-024</td><td>01:42 ago</td></tr><tr><td><span class="activity-type submit"><i></i>Tests passed</span></td><td>All 4 public test cases passed.</td><td>M-024</td><td>01:08 ago</td></tr><tr><td><span class="activity-type result"><i></i>Match completed</span></td><td>Byte Me defeated Null Pointers · +180 pts.</td><td>M-018</td><td>Yesterday</td></tr></tbody></table></section><section class="panel page-panel"><div class="section-kicker">PRIVACY</div><h3 style="margin:4px 0 7px;font:600 13px var(--display)">Attack attribution is private</h3><p>Participant activity shows that an attack occurred. The detective's identity and complete attack audit are visible only to event administrators.</p></section>`;$('#exportLog').addEventListener('click',()=>toast('Activity log export is ready'))}
function setRemaining(sec){app.seconds=sec;const m=String(Math.floor(sec/60)).padStart(2,'0'),s=String(sec%60).padStart(2,'0');const html=`<span>${m}</span><i>:</i><span>${s}</span>`;const dashboard=$('#dashboardTimer');if(dashboard)dashboard.innerHTML=html;$$('.side-timer').forEach(x=>x.textContent=`${m}:${s}`);$$('.timer-progress span').forEach(x=>x.style.width=`${Math.max(0,sec/900*100)}%`);if(sec===0&&app.currentMatchId){toast('Match timer ended · submissions are closed');if(app.view==='match'){$$('#view-match button').forEach(b=>b.disabled=true)}}}
function renderView(view){if(app.user?.role==='admin'&&view==='teams')return renderAdminTeams();if(app.user?.role==='admin'&&view==='problems')return renderAdminProblems();if(app.user?.role==='admin'&&view==='activity')return renderAdminAudit();const renderers={match:renderMatch,tournament:renderTournament,leaderboard:renderLeaderboard,results:renderResults,teams:renderTeams,problems:renderProblems,activity:renderActivity};const render=renderers[view];if(render)render()}
async function renderAdminTeams(){const el=$('#view-teams');el.innerHTML=`${pageHead('ORGANIZER · TEAMS','Team management','Manage rosters, groups, and qualification status.')}<section class="panel page-panel"><div class="section-heading"><div><div class="section-kicker">60 TEAM CAPACITY</div><h3>Registered teams</h3></div><button class="button button-lime" id="importTeam">+ Add team</button></div><p style="margin:9px 0;color:#8b919b;font-size:9px">Add teams with three to five participant credentials using the documented team creation API. Existing team group/name can be edited below.</p><div style="overflow:auto"><table class="leaderboard-table"><thead><tr><th>TEAM</th><th>CODE</th><th>GROUP</th><th>MEMBERS</th><th>STATUS</th><th></th></tr></thead><tbody id="adminTeamsBody"><tr><td colspan="6">Loading…</td></tr></tbody></table></div></section>`;$('#importTeam').onclick=()=>openModal('Create a team','TEAM ROSTER API','Create a team with three to five participants through POST /api/tournament/teams. The API validates three to five unique email/password accounts in one transaction. See API documentation for the request format.');try{const r=await api('/tournament/teams');$('#adminTeamsBody').innerHTML=r.teams.map(t=>`<tr><td>${escapeHtml(t.name)}</td><td class="mono">${escapeHtml(t.code)}</td><td>${escapeHtml(t.group_name||'—')}</td><td>${t.member_count}/5</td><td>${escapeHtml(t.status)}</td><td><button class="text-button" data-edit-team="${t.id}" data-name="${escapeHtml(t.name)}" data-group="${escapeHtml(t.group_name||'')}">Edit</button></td></tr>`).join('');$$('[data-edit-team]').forEach(b=>b.onclick=async()=>{const name=prompt('Team name',b.dataset.name);if(name===null)return;const groupName=prompt('Group name',b.dataset.group);if(groupName===null)return;try{await api(`/tournament/teams/${b.dataset.editTeam}`,{method:'PATCH',body:JSON.stringify({name,groupName})});toast('Team updated');renderAdminTeams()}catch(e){toast(e.message)}})}catch(e){$('#adminTeamsBody').innerHTML=`<tr><td colspan="6">${escapeHtml(e.message)}</td></tr>`}}
async function renderAdminProblems(){const el=$('#view-problems');el.innerHTML=`${pageHead('ORGANIZER · CHALLENGES','Problem management','Create challenges and manage public and hidden test cases.')}<section class="panel page-panel"><div class="section-heading"><div><div class="section-kicker">CHALLENGE LIBRARY</div><h3>Problems</h3></div><button class="button button-lime" id="createProblem">+ New problem</button></div><div class="problem-list" id="adminProblemList" style="margin-top:13px">Loading…</div></section>`;$('#createProblem').onclick=()=>openProblemForm();try{const r=await api('/problems');$('#adminProblemList').innerHTML=r.problems.map(p=>`<article class="panel problem-row"><span class="problem-symbol">⌘</span><div class="problem-copy"><strong>${escapeHtml(p.title)}</strong><span>${escapeHtml(p.difficulty)} · ${p.public_cases} public cases · ${p.hidden_cases} hidden cases</span></div><span class="problem-stat">${p.time_limit_ms} ms</span><button class="text-button" data-disable-problem="${p.id}">Archive</button></article>`).join('')||'No problems yet.';$$('[data-disable-problem]').forEach(b=>b.onclick=async()=>{try{await api(`/problems/${b.dataset.disableProblem}`,{method:'DELETE'});toast('Problem archived');renderAdminProblems()}catch(e){toast(e.message)}})}catch(e){$('#adminProblemList').textContent=e.message}}
function openProblemForm(){const modal=$('#modalBackdrop');$('#modalKicker').textContent='NEW CHALLENGE';$('#modalTitle').textContent='Create a problem';$('#modalCopy').textContent='Add at least one public and one hidden test case as JSON. Hidden case contents are only visible to organizers.';$('.modal-steps').innerHTML=`<form id="problemForm"><label>Title<input name="title" required minlength="3"></label><label>Description<textarea name="description" required minlength="10" rows="3"></textarea></label><label>Difficulty<select name="difficulty"><option>easy</option><option selected>medium</option><option>hard</option></select></label><label>Test cases JSON<textarea name="testCases" rows="5" placeholder='[{"input":"5\\n1 2 3 4 5","output":"3","hidden":false}]'></textarea></label><p class="login-error" id="problemError"></p><button class="button button-lime" type="submit">Save problem →</button></form>`;$('#modalAction').hidden=true;modal.classList.add('open');$('#problemForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{const testCases=JSON.parse(f.get('testCases')||'[]');await api('/problems',{method:'POST',body:JSON.stringify({title:f.get('title'),description:f.get('description'),difficulty:f.get('difficulty'),testCases})});closeModal();toast('Problem created');renderAdminProblems()}catch(err){$('#problemError').textContent=err.message}}}
async function renderAdminAudit(){const el=$('#view-activity');el.innerHTML=`${pageHead('ORGANIZER · SECURITY','Audit log','Administrative view of match actions and account activity.')}<section class="panel page-panel"><div class="section-heading"><h3>Recent audit events</h3><button class="text-button" id="refreshAudit">Refresh ↻</button></div><div style="overflow:auto"><table class="activity-table"><thead><tr><th>TIME</th><th>ACTOR</th><th>ACTION</th><th>RESOURCE</th><th>DETAILS</th></tr></thead><tbody id="auditRows"><tr><td colspan="5">Loading…</td></tr></tbody></table></div></section>`;const load=async()=>{try{const r=await api('/tournament/audit');$('#auditRows').innerHTML=r.logs.map(x=>`<tr><td>${new Date(x.created_at).toLocaleString()}</td><td>${escapeHtml(x.email||'system')}</td><td>${escapeHtml(x.action)}</td><td>${escapeHtml(x.resource_type)} ${escapeHtml(x.resource_id||'')}</td><td class="mono">${escapeHtml(JSON.stringify(x.metadata))}</td></tr>`).join('')}catch(e){$('#auditRows').innerHTML=`<tr><td colspan="5">${escapeHtml(e.message)}</td></tr>`}};$('#refreshAudit').onclick=load;load()}
async function renderResults(){const el=$('#view-results');el.innerHTML=`${pageHead('FINAL · LIVE RESULTS','Final standings','Five finalists. One challenge. Results are server ranked.')}<section class="panel page-panel"><div class="section-heading"><div><div class="section-kicker">GRAND FINAL</div><h3>Final competition</h3></div><span class="live-pill"><i></i> LIVE RANKING</span></div><div id="finalResultsBody" style="padding-top:14px">Loading final results…</div></section>`;try{const data=await api('/final/current');const body=$('#finalResultsBody');if(!data.contest){body.innerHTML='<p>No final competition has been created yet. The organizer can select the five group winners when group matches are complete.</p>';return}body.innerHTML=`<p style="margin-bottom:12px">Status: <b>${escapeHtml(data.contest.state)}</b>${data.contest.ends_at?` · Ends ${new Date(data.contest.ends_at).toLocaleTimeString()}`:''}</p><table class="leaderboard-table"><thead><tr><th>RANK</th><th>TEAM</th><th>STATUS</th><th>TESTS</th><th>SCORE</th><th>TIME</th></tr></thead><tbody>${data.entries.map(e=>`<tr class="${e.team_id===app.team?.id?'you':''}"><td>${e.rank?`#${e.rank}`:'—'}</td><td>${escapeHtml(e.team_name)}${e.team_id===app.team?.id?' <span class="activity-tag">YOU</span>':''}</td><td>${escapeHtml(e.status)}</td><td>${e.total_tests?`${e.passed_tests}/${e.total_tests}`:'—'}</td><td>${Number(e.score||0).toFixed(1)}</td><td>${e.completion_ms?`${(e.completion_ms/1000).toFixed(1)}s`:'—'}</td></tr>`).join('')}</tbody></table>${data.contest.state==='ACTIVE'&&data.own?`<section style="margin-top:18px"><div class="section-kicker">YOUR FINAL SUBMISSION</div><p style="margin:5px 0 10px">Enter your C or C++ solution. Hidden case details remain private.</p><select id="finalLanguage" class="language-select"><option>C</option><option selected>C++</option></select><textarea id="finalSourceCode" class="code-area final-code-area" spellcheck="false" aria-label="Final solution">${escapeHtml(app.code[app.language]||'')}</textarea><button class="button button-lime" id="finalSubmit">Submit final solution <span>&rarr;</span></button></section>`:''}`;if($('#finalLanguage'))$('#finalLanguage').value=app.language;$('#finalSubmit')?.addEventListener('click',async()=>{const sourceCode=$('#finalSourceCode').value;const language=$('#finalLanguage').value;try{const r=await api(`/final/${data.contest.id}/submit`,{method:'POST',body:JSON.stringify({sourceCode,language:languageCode(language)})});toast(`Final ${r.status} · rank ${r.rank??'pending'}`);renderResults()}catch(e){toast(e.message)}})}catch(e){$('#finalResultsBody').textContent=e.message}}
function openModal(title='Play sharp. Play fair.',kicker='COMPETITION GUIDE',copy='Two teams. One challenge. The coder builds while the detective looks for a weakness using a limited set of controlled attacks.'){ $('#modalTitle').textContent=title;$('#modalKicker').textContent=kicker;$('#modalCopy').textContent=copy;$('.modal-steps').innerHTML='<div><span>01</span><p><b>Code the solution</b><small>Run your program against public tests.</small></p></div><div><span>02</span><p><b>Watch for changes</b><small>Detective attacks are limited and logged.</small></p></div><div><span>03</span><p><b>Submit before time</b><small>The server checks your solution against hidden tests.</small></p></div>';$('#modalAction').hidden=false;$('#modalBackdrop').classList.add('open');$('#modalBackdrop').setAttribute('aria-hidden','false')}
