function init(){ $$('.nav-item').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.view)));$$('[data-navigate]').forEach(b=>b.addEventListener('click',e=>{e.preventDefault();navigate(b.dataset.navigate)}));$('#guideButton')?.addEventListener('click',()=>openModal());$('#modalClose')?.addEventListener('click',closeModal);$('#modalAction')?.addEventListener('click',closeModal);$('#modalBackdrop')?.addEventListener('click',e=>{if(e.target===$('#modalBackdrop'))closeModal()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});$('#mobileMenu')?.addEventListener('click',()=>$('#sidebar')?.classList.toggle('open'));$('#notificationsButton')?.addEventListener('click',()=>toast('You are all caught up.'));$('#profileButton')?.addEventListener('click',()=>toast(app.user?`Signed in as ${app.user.name}`:'Account profile'));$('#supportLink')?.addEventListener('click',e=>{e.preventDefault();openModal('We’ve got your back.','COMPETITION SUPPORT','For help during a live match, ask your event room coordinator. Match and timer issues are automatically logged for the organizers.')});setRemaining(app.seconds);setInterval(()=>{if(app.seconds>0)setRemaining(app.seconds-1)},1000);}
