  adminRegisterCard.innerHTML=`<a class="brand login-brand" href="#"><span class="brand-mark"><span></span><span></span><span></span></span><span class="brand-name">find<span class="brand-accent">.</span>hacker</span></a><div class="section-kicker">ORGANIZER ACCOUNT</div><h1>Register as an organizer.</h1><p>Organizer accounts require the private invitation key configured by the system owner.</p><form id="adminRegistrationForm"><label for="adminRegisterName">Full name</label><input id="adminRegisterName" name="name" required minlength="2" maxlength="80" autocomplete="name"><label for="adminRegisterEmail">Email address</label><input id="adminRegisterEmail" name="email" type="email" required maxlength="254" autocomplete="email"><label for="adminRegisterPassword">Password</label><input id="adminRegisterPassword" name="password" type="password" required minlength="16" maxlength="200" autocomplete="new-password"><label for="adminInviteCode">Organizer invitation key</label><input id="adminInviteCode" name="inviteCode" type="password" required autocomplete="off"><div class="login-error" id="adminRegistrationError" role="alert"></div><button class="button button-lime login-submit" type="submit">Create organizer account <span>→</span></button></form><button class="text-button register-link" id="backFromAdminRegistration" type="button">← Back to sign in</button>`;
