  $('#showAdminRegistration').addEventListener('click',()=>{loginForm.hidden=true;adminRegisterCard.hidden=false;$('#adminRegisterName').focus()});
  $('#backToLogin').addEventListener('click',()=>{registerCard.hidden=true;loginForm.hidden=false});
  $('#backFromTeamJoin').addEventListener('click',()=>{joinCard.hidden=true;loginForm.hidden=false});
  $('#backFromAdminRegistration').addEventListener('click',()=>{adminRegisterCard.hidden=true;loginForm.hidden=false});
  loginForm.addEventListener('submit',async e=>{e.preventDefault();const error=$('#loginError');error.textContent='';const button=$('.login-submit',loginForm);button.disabled=true;try{const result=await api('/auth/login',{method:'POST',body:JSON.stringify({email:$('#loginEmail').value,password:$('#loginPassword').value})});app.token=result.token;await establishSession();$('#loginScreen').classList.remove('open');$('#loginScreen').setAttribute('aria-hidden','true')}catch(err){error.textContent=err.message}finally{button.disabled=false}});
  $('#teamRegistrationForm').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget;const error=$('#registrationError');const button=$('button[type="submit"]',form);error.textContent='';button.disabled=true;button.textContent='Creating team…';try{const data=new FormData(form);const members=Array.from({length:participantCount},(_,i)=>({name:data.get(`member${i}Name`),email:data.get(`member${i}Email`),...(i===0?{password:data.get('member0Password')}:{})}));const result=await api('/registration',{method:'POST',body:JSON.stringify({teamName:data.get('teamName'),members})});app.token=result.token;await establishSession();$('#loginScreen').classList.remove('open');$('#loginScreen').setAttribute('aria-hidden','true');toast(`Team created. Share join code ${result.team.code} with your teammates.`)}catch(err){error.textContent=err.message}finally{button.disabled=false;button.innerHTML='Create team and get code <span>→</span>'}});
  $('#teamJoinForm').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget;const error=$('#teamJoinError');const button=$('button[type="submit"]',form);const data=new FormData(form);error.textContent='';button.disabled=true;button.textContent='Joining team…';try{const result=await api('/registration/join',{method:'POST',body:JSON.stringify({code:data.get('code'),email:data.get('email'),password:data.get('password')})});app.token=result.token;await establishSession();$('#loginScreen').classList.remove('open');$('#loginScreen').setAttribute('aria-hidden','true');toast(result.pairing?`Team complete. Match ready as ${result.pairing.role}.`:'You joined the team. Waiting for the remaining teammates to join.')}catch(err){error.textContent=err.message}finally{button.disabled=false;button.innerHTML='Join team <span>→</span>'}});
  $('#adminRegistrationForm').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget;const error=$('#adminRegistrationError');const button=$('button[type="submit"]',form);const data=new FormData(form);error.textContent='';button.disabled=true;button.textContent='Registering organizer…';try{const result=await api('/registration/admin',{method:'POST',body:JSON.stringify({name:data.get('name'),email:data.get('email'),password:data.get('password'),inviteCode:data.get('inviteCode')})});app.token=result.token;await establishSession();$('#loginScreen').classList.remove('open');$('#loginScreen').setAttribute('aria-hidden','true');toast('Organizer account created')}catch(err){error.textContent=err.message}finally{button.disabled=false;button.innerHTML='Create organizer account <span>→</span>'}});
  establishSession().catch(()=>{$('#loginScreen').classList.add('open');$('#loginScreen').setAttribute('aria-hidden','false')})
