startApplication();

const renderResultsBeforeAdminControls=renderResults;
renderResults=async function(){await renderResultsBeforeAdminControls();if(app.user?.role!=='admin')return;try{const {contest}=await api('/final/current');if(!contest)return;const body=$('#finalResultsBody');if(!body)return;const controls=document.createElement('div');controls.className='final-admin-controls';controls.innerHTML=contest.state==='READY'?'<button class="button button-lime" id="startFinal">Start final timer</button>':contest.state==='ACTIVE'?'<button class="button button-secondary" id="completeFinal">Complete final and publish places</button>':'';body.append(controls);$('#startFinal')?.addEventListener('click',async()=>{try{await api(`/final/${contest.id}/start`,{method:'POST',body:'{}'});toast('Final started');await renderResults()}catch(error){toast(error.message)}});$('#completeFinal')?.addEventListener('click',async()=>{try{const result=await api(`/final/${contest.id}/complete`,{method:'POST',body:'{}'});toast(`Final completed. ${result.podium.length} places published.`);await renderResults()}catch(error){toast(error.message)}})}catch(error){toast(error.message)}};
